new_authentication:
def authenticate():
    freeze = load(PACKAGE / 'FREEZE.json')
    assert digest(PACKAGE / 'INPUTS.json') == freeze['inputs_sha256']
    inputs = load(PACKAGE / 'INPUTS.json')
    assert len(inputs) == freeze['entries']
    for rel, sha in inputs.items():
        assert digest(PACKAGE / rel) == sha, rel
    for directory, pins in load(PACKAGE / 'DEPENDENCIES.json').items():
        dependency = PACKAGE.parent / directory
        assert digest(dependency / 'FREEZE.json') == pins['freeze_sha256'], directory
        assert digest(dependency / 'INPUTS.json') == pins['inputs_sha256'], directory
        for rel, sha in load(dependency / 'INPUTS.json').items():
            assert digest(dependency / rel) == sha, (directory, rel)
